char *simplifyPath(char *path) {
  int n = strlen(path);
  char **stack = (char **)malloc(sizeof(char *) * (n + 1));
  int top = 0;
  char *token = strtok(path, "/");
  while (token) {
    if (strcmp(token, ".") == 0) {
      // skip
    } else if (strcmp(token, "..") == 0) {
      if (top > 0) top--;
    } else {
      stack[top++] = token;
    }
    token = strtok(NULL, "/");
  }
  char *res = (char *)malloc(n + 2);
  int p = 0;
  for (int i = 0; i < top; i++) {
    res[p++] = '/';
    int l = strlen(stack[i]);
    memcpy(res + p, stack[i], l);
    p += l;
  }
  if (top == 0) res[p++] = '/';
  res[p] = '\0';
  free(stack);
  return res;
}

class Solution {
public:
  string simplifyPath(string path) {
    vector<string> st;
    stringstream ss(path);
    string tok;
    while (getline(ss, tok, '/')) {
      if (tok == "" || tok == ".") {
        continue;
      }
      if (tok == "..") {
        if (!st.empty()) st.pop_back();
      } else {
        st.push_back(tok);
      }
    }
    string res;
    for (const string &s : st) res += "/" + s;
    return res.empty() ? "/" : res;
  }
};

func simplifyPath(path string) string {
	parts := strings.Split(path, "/")
	var st []string
	for _, p := range parts {
		if p == "" || p == "." {
			continue
		}
		if p == ".." {
			if len(st) > 0 {
				st = st[:len(st)-1]
			}
		} else {
			st = append(st, p)
		}
	}
	return "/" + strings.Join(st, "/")
}

class Solution {
  public String simplifyPath(String path) {
    Deque<String> st = new ArrayDeque<>();
    for (String tok : path.split("/")) {
      if (tok.isEmpty() || tok.equals(".")) {
        continue;
      }
      if (tok.equals("..")) {
        if (!st.isEmpty()) st.pollLast();
      } else {
        st.addLast(tok);
      }
    }
    if (st.isEmpty()) {
      return "/";
    }
    StringBuilder sb = new StringBuilder();
    for (String s : st) {
      sb.append('/').append(s);
    }
    return sb.toString();
  }
}

class Solution:
    def simplifyPath(self, path: str) -> str:
        st = []
        for tok in path.split("/"):
            if tok == "" or tok == ".":
                continue
            if tok == "..":
                if st:
                    st.pop()
            else:
                st.append(tok)
        return "/" + "/".join(st)

impl Solution {
  pub fn simplify_path(path: String) -> String {
    let mut st: Vec<&str> = vec![];
    for tok in path.split('/') {
      if tok.is_empty() || tok == "." {
        continue;
      }
      if tok == ".." {
        st.pop();
      } else {
        st.push(tok);
      }
    }
    format!("/{}", st.join("/"))
  }
}

const simplifyPath = (path: string): string => {
  const st: string[] = [];
  for (const tok of path.split('/')) {
    if (tok === '' || tok === '.') continue;
    if (tok === '..') {
      st.pop();
    } else {
      st.push(tok);
    }
  }
  return '/' + st.join('/');
};
